import type { AccordionGalleryItem, AccordionTweenTrack } from './types';

export const ACCORDION_GALLERY_DEFAULT_ITEMS: AccordionGalleryItem[] = [
  {
    image: 'https://picsum.photos/id/1015/900/1200',
    label: 'Canyon',
    link: '#',
  },
  {
    image: 'https://picsum.photos/id/1018/900/1200',
    label: 'Ridgeline',
    link: '#',
  },
  {
    image: 'https://picsum.photos/id/1039/900/1200',
    label: 'Falls',
    link: '#',
  },
  {
    image: 'https://picsum.photos/id/1043/900/1200',
    label: 'Harbour',
    link: '#',
  },
  {
    image: 'https://picsum.photos/id/1044/900/1200',
    label: 'Skyline',
    link: '#',
  },
];

type Curve = (t: number) => number;

const powerOut =
  (p: number): Curve =>
  (t) =>
    1 - (1 - t) ** p;
const powerIn =
  (p: number): Curve =>
  (t) =>
    t ** p;
const powerInOut =
  (p: number): Curve =>
  (t) =>
    t < 0.5 ? 2 ** (p - 1) * t ** p : 1 - (-2 * t + 2) ** p / 2;

const BACK = 1.70158;

const CURVES: Record<string, Curve> = {
  none: (t) => t,
  linear: (t) => t,
  'sine.in': (t) => 1 - Math.cos((t * Math.PI) / 2),
  'sine.out': (t) => Math.sin((t * Math.PI) / 2),
  'sine.inOut': (t) => -(Math.cos(Math.PI * t) - 1) / 2,
  'expo.in': (t) => (t === 0 ? 0 : 2 ** (10 * t - 10)),
  'expo.out': (t) => (t === 1 ? 1 : 1 - 2 ** (-10 * t)),
  'expo.inOut': (t) =>
    t === 0 || t === 1
      ? t
      : t < 0.5
        ? 2 ** (20 * t - 10) / 2
        : (2 - 2 ** (-20 * t + 10)) / 2,
  'circ.out': (t) => Math.sqrt(1 - (t - 1) ** 2),
  'back.out': (t) => 1 + (BACK + 1) * (t - 1) ** 3 + BACK * (t - 1) ** 2,
};

for (let p = 1; p <= 4; p++) {
  CURVES[`power${p}.out`] = powerOut(p + 1);
  CURVES[`power${p}.in`] = powerIn(p + 1);
  CURVES[`power${p}.inOut`] = powerInOut(p + 1);
  CURVES[`power${p}`] = powerOut(p + 1);
}

/** Resolves a GSAP-style ease name ("power3.out", "expo.inOut", "none") to a curve. */
export function resolveEase(name: string): Curve {
  const key = name.replace(/\(.*\)$/, '');
  return CURVES[key] ?? CURVES['power3.out'] ?? powerOut(4);
}

/** Runs a set of numeric tracks on one rAF loop. Returns a cancel function. */
export function runTracks(
  tracks: AccordionTweenTrack[],
  ease: Curve,
): () => void {
  let frame = 0;
  let start = -1;
  const finishAll = () => {
    for (const track of tracks) track.apply(track.to);
  };
  const instant = tracks.every((t) => t.duration <= 0 && t.delay <= 0);
  if (instant) {
    finishAll();
    return () => {};
  }
  const step = (now: number) => {
    if (start < 0) start = now;
    const elapsed = (now - start) / 1000;
    let running = false;
    for (const track of tracks) {
      const local = elapsed - track.delay;
      if (local < 0) {
        running = true;
        continue;
      }
      const t = track.duration <= 0 ? 1 : Math.min(local / track.duration, 1);
      if (t < 1) running = true;
      track.apply(track.from + (track.to - track.from) * ease(t));
    }
    if (running) frame = requestAnimationFrame(step);
  };
  frame = requestAnimationFrame(step);
  return () => cancelAnimationFrame(frame);
}

export { default as AccordionGallery } from './AccordionGallery.vue';
export { ACCORDION_GALLERY_DEFAULT_ITEMS } from './accordion-tween';
export type {
  AccordionGalleryItem,
  AccordionGalleryOrientation,
  AccordionGalleryProps,
  AccordionGalleryTrigger,
} from './types';

import type { HTMLAttributes } from 'vue';

export interface AccordionGalleryItem {
  /** Image URL. */
  image: string;
  /** Caption shown on the open panel and its accessible name. */
  label?: string;
  /** When set, the panel is a link. The first click on a closed panel only opens it. */
  link?: string;
  /** Alt text. Falls back to the label. */
  alt?: string;
}

export type AccordionGalleryOrientation = 'horizontal' | 'vertical';

export type AccordionGalleryTrigger = 'hover' | 'click';

export interface AccordionGalleryProps {
  /** Panels to display. */
  items?: AccordionGalleryItem[];
  /** Index of the panel that starts open. */
  defaultIndex?: number;
  /** Colour of the caption bar and focus ring. */
  accentColor?: string;
  /** Tint over closed panels and the caption gradient. */
  overlayColor?: string;
  /** Caption text colour. */
  textColor?: string;
  /** Height in pixels (vertical orientation uses 1.6×). */
  height?: number;
  /** Space between panels in pixels. */
  gap?: number;
  /** Corner radius of each panel in pixels. */
  radius?: number;
  /** Share of the row the open panel takes (0.2–0.9). */
  expandRatio?: number;
  /** Lay panels out in a row or a column. */
  orientation?: AccordionGalleryOrientation;
  /** Transition length in seconds. */
  duration?: number;
  /** GSAP-style ease name, e.g. "power3.out", "expo.inOut", "none". */
  ease?: string;
  /** How far closed images shift toward the open panel (0 disables it). */
  parallax?: number;
  /** 3D tilt of closed panels in degrees. */
  tilt?: number;
  /** Delay between the caption bar and the caption text in seconds. */
  stagger?: number;
  /** Open a panel on hover or only on click. */
  trigger?: AccordionGalleryTrigger;
  /** Show the caption on the open panel. */
  showLabels?: boolean;
  /** Closed panels are grayscale; the open one is in colour. */
  grayscale?: boolean;
  class?: HTMLAttributes['class'];
}

export interface AccordionTweenTrack {
  from: number;
  to: number;
  delay: number;
  duration: number;
  apply: (value: number) => void;
}

export interface AccordionPanelState {
  grow: number;
  rot: number;
  mx: number;
  my: number;
  gray: number;
  dim: number;
  barOpacity: number;
  barX: number;
  textOpacity: number;
  textX: number;
}
